const npcState=[];
const bonds=[];
const bondKey=(a,b)=>[a,b].sort().join('|');
const initialBonds=[
 ['Mina','Theo',-38],['Inez','Cal',54],['Inez','June',22],['Ruth','Ari',34],
 ['Ruth','Sol',42],['Sol','June',56],['Theo','Cal',-20],['Ari','June',8]
];
for(const [a,b,score] of initialBonds)bonds.push({key:bondKey(a,b),a,b,score,meetings:0,together:false});
function getBond(a,b){const key=bondKey(a,b);let bond=bonds.find(item=>item.key===key);if(!bond){bond={key,a,b,score:0,meetings:0,together:false};bonds.push(bond)}return bond}
function bondDescription(bond){if(bond.score>=30)return'close friends';if(bond.score>=10)return'becoming friends';if(bond.score<=-30)return'rivals';if(bond.score<=-10)return'a little wary of each other';return'getting to know each other'}
function bondStory(bond){const a=npcState.find(n=>n.name===bond.a)?.name||bond.a,b=npcState.find(n=>n.name===bond.b)?.name||bond.b;const status=bondDescription(bond);if(bond.meetings===0)return `${a} and ${b} are ${status}.` ;return `${a} and ${b} are ${status}; they have shared ${bond.meetings} ${bond.meetings===1?'conversation':'conversations'} at the town's social hour.`}
function residentDynamics(npc){const related=bonds.filter(b=>b.a===npc.name||b.b===npc.name).filter(b=>b.meetings>0||Math.abs(b.score)>=10).sort((a,b)=>Math.abs(b.score)-Math.abs(a.score));return related.length?related.map(b=>bondStory(b)).join(' '):'No close ties yet. Familiar faces and shared conversations may change that.'}
const residentList=document.querySelector('#residentList');
const residentModal=document.querySelector('#residentModal');
function openResident(npc){document.querySelector('#residentName').textContent=npc.family;document.querySelector('#residentActivity').textContent=`${npc.name} · ${activityInfo[npc.activity]?.label||'at home'}`;document.querySelector('#residentRelationships').textContent=npc.relationships;document.querySelector('#residentDynamics').textContent=residentDynamics(npc);document.querySelector('#residentProblem').textContent=npc.problem;document.querySelector('#residentStory').textContent=npc.story;residentModal.classList.add('open')}

