const bonds=[];
const playerMemories=(()=>{try{return JSON.parse(localStorage.getItem('elsewhere-player-memories')||'{}')}catch{return{}}})();
const playerDialogues={
 Mina:['You’re the one keeping the field guide. Lila would like that—she collects little records of things, too.','You came back. That means the county is starting to feel familiar, doesn’t it?','I told Lila about your walks. She wants to know what you’ll find next.'],
 Theo:['If you’re writing things down, write this: a place can look abandoned without being empty.','Back again? I suppose it’s good to see someone paying attention around here.','You’ve earned the honest version: I’m glad you keep coming by.'],
 Inez:['You look like you’ve been walking a while. The clinic garden is quiet if you need a rest.','I was wondering when you’d come by again. How is the county looking to you?','I’ve started saving the small things you tell me. They make the days feel less lonely.'],
 Cal:['Can you speak up just a little? I don’t want to miss what you’ve been finding.','I remember you. You’re the one making a map of places most folks pass by.','It’s good having someone to compare notes with. I trust your eye for a detail.'],
 Ruth:['A good walk can make a person notice what they’ve been carrying. What did you notice today?','You’ve been back a few times. I’m beginning to think of you as part of the neighborhood.','I saved you a book recommendation. You seem like someone who lets a story linger.'],
 Ari:['I’ve been drawing the places you find. The ones you describe always look a little different in my sketchbook.','You came back! Tell me one thing you saw that you think nobody else noticed.','I put a little mark for you on my county map. You’re part of it now.'],
 Sol:['The library keeps records of places. I suppose you’re making your own kind of catalog.','I remember your notes. They’re becoming a useful map of the things people overlook.','I’ve added you to my unofficial catalog: “people who come back and pay attention.”'],
 June:['You’re the one exploring the county, right? I keep meaning to ask what you’ve found.','You came back. Maybe there’s more to this place than I thought.','I like that you keep showing up. It makes leaving feel a little less simple.']
};
const bondKey=(a,b)=>[a,b].sort().join('|');

