const nearby=document.querySelector('#nearby'),nearName=document.querySelector('#nearName'),nearType=document.querySelector('#nearType'),nearPrompt=document.querySelector('#nearPrompt'),actionBtn=document.querySelector('#actionBtn');let activeSite=-1;
function findNearest(){let best=-1,dist=Infinity;for(let i=0;i<sites.length;i++){let d=siteDistance(sites[i]);if(d<dist){dist=d;best=i}}return dist<7.2?best:-1}
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function recordSite(){if(activeSite<0)return;const s=sites[activeSite];if(found.has(activeSite)){toast(`${s.name} — already in your field guide.`);return}found.add(activeSite);localStorage.setItem('elsewhere-notes',JSON.stringify([...found]));paintProgress();const event=countyEvents.find(item=>item.siteIndex===activeSite);toast(event?event.toast:found.size===sites.length?`Atlas complete. You found all ${sites.length} places.`:`Field note recorded: ${s.name}`)}
