const nearby=document.querySelector('#nearby'),nearName=document.querySelector('#nearName'),nearType=document.querySelector('#nearType'),nearPrompt=document.querySelector('#nearPrompt'),actionBtn=document.querySelector('#actionBtn');let activeSite=-1,activeNpc=null;
function findNearest(){let best=-1,dist=Infinity;for(let i=0;i<sites.length;i++){let d=siteDistance(sites[i]);if(d<dist){dist=d;best=i}}return dist<7.2?best:-1}
function findNearestNpc(){let best=null,dist=Infinity;for(const npc of npcState){const d=Math.hypot(player.x-npc.x,player.z-npc.z);if(d<dist){dist=d;best=npc}}return dist<3.2?best:null}
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function recordSite(){if(activeNpc){talkToResident(activeNpc);return}if(activeSite<0)return;const s=sites[activeSite];if(found.has(activeSite)){toast(`${s.name} — already in your field guide.`);return}found.add(activeSite);localStorage.setItem('elsewhere-notes',JSON.stringify([...found]));paintProgress();const event=countyEvents.find(item=>item.siteIndex===activeSite);toast(event?event.toast:found.size===sites.length?`Atlas complete. You found all ${sites.length} places.`:`Field note recorded: ${s.name}`)}
function updateNearby(){const npc=findNearestNpc();if(npc===activeNpc&&(!npc||activeSite===findNearest()))return;activeNpc=npc;activeSite=npc?-1:findNearest();if(npc){nearName.textContent=npc.name;nearType.textContent=`RESIDENT · ${activityInfo[npc.activity]?.label||'at home'}`;nearPrompt.innerHTML=matchMedia('(max-width:700px)').matches?'Tap <b>TALK</b> to speak with them':'Press <b>E</b> to talk';actionBtn.querySelector('.action-label').textContent='TALK';actionBtn.setAttribute('aria-label',`Talk with ${npc.name}`);nearby.classList.add('show');actionBtn.disabled=false;actionBtn.classList.add('ready');return}if(activeSite<0){nearby.classList.remove('show');actionBtn.disabled=true;actionBtn.classList.remove('ready');return}const s=sites[activeSite];nearName.textContent=s.name;nearType.textContent=`${s.icon}  ${s.type}`;nearPrompt.innerHTML=matchMedia('(max-width:700px)').matches?'Tap <b>RECORD</b> to add this place':'Press <b>E</b> to record this place';actionBtn.querySelector('.action-label').textContent='RECORD';actionBtn.setAttribute('aria-label','Record field note');nearby.classList.add('show');actionBtn.disabled=false;actionBtn.classList.add('ready')}

