+ {site:'Drain 9',headline:'The water running uphill',toast:'County news: people swear the current in Drain 9 runs uphill. Cal heard the same thing on the radio; Ari says the water in her sketch is moving the wrong way.',reactions:{Mina:'She tells Lila not to go near the drain, then admits she has always wondered what is down there.',Theo:'He says a slope can fool your eyes, but volunteers to check the tunnel anyway.',Inez:'She remembers the clinic weather vane pointing against the wind on the same night.',Cal:'He is sure a caller described the uphill current years ago, in a voice he still recognizes.',Ruth:'She finds an old library clipping about water flowing toward the ridge, dated decades apart.',Ari:'She has drawn the current moving uphill without meaning to; now she cannot make it flow the other way.',Sol:'He has found the same impossible observation in three unrelated county records.',June:'She says she will believe it when she sees it, then avoids looking away from the drain.'}}
+].map(event=>({...event,siteIndex:sites.findIndex(site=>site.name===event.site)}));
+for(const [a,b,score] of initialBonds)bonds.push({key:bondKey(a,b),a,b,score,meetings:0,lastDay:-1,together:false});
+function getBond(a,b){const key=bondKey(a,b);let bond=bonds.find(item=>item.key===key);if(!bond){bond={key,a,b,score:0,meetings:0,lastDay:-1,together:false};bonds.push(bond)}return bond}
+function bondDescription(bond){if(bond.score>=30)return'close friends';if(bond.score>=10)return'becoming friends';if(bond.score<=-30)return'rivals';if(bond.score<=-10)return'a little wary of each other';return'getting to know each other'}
+function bondStory(bond){const a=npcState.find(n=>n.name===bond.a)?.name||bond.a,b=npcState.find(n=>n.name===bond.b)?.name||bond.b;const status=bondDescription(bond);if(bond.meetings===0)return `${a} and ${b} are ${status}.` ;return `${a} and ${b} are ${status}; they have shared ${bond.meetings} ${bond.meetings===1?'conversation':'conversations'} at the town's social hour.`}
+function residentDynamics(npc){const related=bonds.filter(b=>b.a===npc.name||b.b===npc.name).filter(b=>b.meetings>0||Math.abs(b.score)>=10).sort((a,b)=>Math.abs(b.score)-Math.abs(a.score));return related.length?related.map(b=>bondStory(b)).join(' '):'No close ties yet. Familiar faces and shared conversations may change that.'}
+function playerMemory(npc){return playerMemories[npc.name]||(playerMemories[npc.name]={visits:0,lastLine:''})}
+function playerGreeting(npc){const memory=playerMemory(npc);const lines=playerDialogues[npc.name];if(memory.visits===0)return lines[0];if(memory.visits===1)return lines[1];return lines[2]}
+function talkToResident(npc){const memory=playerMemory(npc),greeting=playerGreeting(npc),place=findNearest();memory.visits++;memory.lastLine=greeting;memory.lastPlace=place>=0?sites[place].name:null;memory.lastTime=countyTime.textContent;localStorage.setItem('elsewhere-player-memories',JSON.stringify(playerMemories));toast(`${npc.name}: “${greeting}”`);renderResidents()}
+function residentWhispers(npc){const heard=countyEvents.filter(event=>found.has(event.siteIndex));return heard.length?heard.map(event=>`${event.headline}: ${event.reactions[npc.name]}`).join(' '):'No unsettling county stories have reached them yet. Record places in the field guide to hear what the residents make of them.'}
 const residentList=document.querySelector('#residentList');
