function rumorFor(npc,event){const entry=rumorMemories[npc.name]?.[event.siteIndex];return entry?event.rumors?.[entry.rumor]:null}
function rememberRumor(npc,event,rumorIndex,from){rumorMemories[npc.name]??={};rumorMemories[npc.name][event.siteIndex]={rumor:rumorIndex,from};localStorage.setItem('elsewhere-rumors',JSON.stringify(rumorMemories))}
function startRumors(event){for(const [index,rumor] of (event.rumors||[]).entries()){const first=rumor.spread[0],npc=npcState.find(person=>person.name===first);if(npc&&!rumorFor(npc,event))rememberRumor(npc,event,index,rumor.source)}}
function passRumor(from,to){for(const event of countyEvents){const entry=rumorMemories[from.name]?.[event.siteIndex],rumor=entry&&event.rumors?.[entry.rumor];if(!rumor||rumorFor(to,event)||!rumor.spread.includes(to.name))continue;rememberRumor(to,event,entry.rumor,from.name);return `${from.name} passed a rumor to ${to.name}: “${rumor.text}”`}}
function residentWhispers(npc){const heard=countyEvents.filter(event=>found.has(event.siteIndex));if(!heard.length)return'No unsettling county stories have reached them yet. Record places in the field guide to hear what the residents make of them.';return heard.map(event=>{const rumor=rumorFor(npc,event),entry=rumorMemories[npc.name]?.[event.siteIndex];return `${event.headline}: ${event.reactions[npc.name]}${rumor?` Rumor (unverified), from ${entry.from}: “${rumor.text}” Known so far: ${rumor.truth}`:' No rumor has reached them about this yet.'}`}).join(' ')}

