function rumorFor(npc,event){const entry=rumorMemories[npc.name]?.[event.siteIndex];return entry?event.rumors?.[entry.rumor]:null}
function uneaseFor(npc){const saved=uneaseMemories[npc.name]||{};return{fear:THREE.MathUtils.clamp(Number(saved.fear)||0,0,100),paranoia:THREE.MathUtils.clamp(Number(saved.paranoia)||0,0,100),exposures:Array.isArray(saved.exposures)?saved.exposures:[]}}
function recordUnease(npc,event,rumorIndex){const state=uneaseFor(npc),exposure=`${event.siteIndex}:${rumorIndex}`;if(state.exposures.includes(exposure))return;state.exposures.push(exposure);const impact=event.unease||{fear:8,paranoia:8};state.fear=THREE.MathUtils.clamp(state.fear+impact.fear+(rumorIndex===0?0:1),0,100);state.paranoia=THREE.MathUtils.clamp(state.paranoia+impact.paranoia+(rumorIndex===0?1:0),0,100);uneaseMemories[npc.name]=state;localStorage.setItem('elsewhere-unease',JSON.stringify(uneaseMemories))}
function rememberRumor(npc,event,rumorIndex,from){rumorMemories[npc.name]??={};rumorMemories[npc.name][event.siteIndex]={rumor:rumorIndex,from};recordUnease(npc,event,rumorIndex);localStorage.setItem('elsewhere-rumors',JSON.stringify(rumorMemories))}
function uneaseLevel(value,kind){if(value<10)return kind==='fear'?'settled':'open';if(value<25)return kind==='fear'?'uneasy':'watchful';if(value<50)return kind==='fear'?'afraid':'suspicious';if(value<75)return kind==='fear'?'frightened':'paranoid';return kind==='fear'?'terrified':'deeply mistrustful'}
function residentUnease(npc){const state=uneaseFor(npc);return `Fear: ${uneaseLevel(state.fear,'fear')} (${state.fear}/100). Paranoia: ${uneaseLevel(state.paranoia,'paranoia')} (${state.paranoia}/100). Unverified stories can leave a mark, even when nobody knows what is true.`}

