+function activityAt(npc,hour){const r=npcRoutines[npc.name];if(hour>=r.bed||hour<r.wake)return'sleep';if(hour>=r.workStart-.5&&hour<r.workStart)return'commute';if(hour>=r.workStart&&hour<r.workEnd)return hour>=r.meal&&hour<r.meal+.65?'eat':'work';if(hour>=r.socialStart&&hour<r.socialEnd)return'social';if(hour>=r.wake&&hour<r.wake+.45)return'eat';if(hour>=19&&hour<20)return'eat';return'home'}
+function anchorFor(npc,activity){const i=npcState.indexOf(npc);if(activity==='sleep'||activity==='home')return{x:npc.homeX,z:npc.homeZ};if(activity==='work'||activity==='commute')return{x:npc.workX,z:npc.workZ};if(activity==='social')return{x:meetSpots[i][0],z:meetSpots[i][1]};if(activity==='errand'&&npc.errandAnchor)return npc.errandAnchor;if(activity==='eat'){if(hourOfDay()>=npcRoutines[npc.name].wake&&hourOfDay()<npcRoutines[npc.name].wake+.6)return{x:npc.homeX+1.4,z:npc.homeZ};const p=foodSpots[i];return{x:p[0],z:p[1]}}return{x:npc.homeX,z:npc.homeZ}}
 function chooseNpcTarget(npc,still=false){if(still){npc.target={x:npc.anchor.x,z:npc.anchor.z};return}for(let i=0;i<18;i++){const ang=rand()*Math.PI*2,radius=.25+rand()*(npc.activity==='social'?1.3:.85),x=npc.anchor.x+Math.cos(ang)*radius,z=npc.anchor.z+Math.sin(ang)*radius;if(!npcCollides(x,z,.62)){npc.target={x,z};return}}npc.target={x:npc.anchor.x,z:npc.anchor.z}}
 function hourOfDay(){return countyMinutes/60%24}
-let countyMinutes=7*60,clockRate=4;
+let countyMinutes=7*60,countyDay=0,clockRate=4;
 const countyTime=document.querySelector('#countyTime');let lastResidentPaint=-1;
-function updateClock(dt){if(started&&!journal.classList.contains('open'))countyMinutes=(countyMinutes+dt*clockRate)%(24*60);const h=Math.floor(countyMinutes/60),m=Math.floor(countyMinutes%60),period=h<12?'AM':'PM',display=((h+11)%12)+1;countyTime.textContent=`${display}:${String(m).padStart(2,'0')} ${period}`;const nextMinute=Math.floor(countyMinutes);if(nextMinute!==lastResidentPaint){lastResidentPaint=nextMinute;let changed=false;for(const npc of npcState){const next=activityAt(hourOfDay());if(npc.activity!==next){npc.activity=next;npc.anchor=anchorFor(npc,next);chooseNpcTarget(npc,next==='sleep');setBadge(npc,next);changed=true}}if(changed||!residentList.childElementCount)renderResidents()}}
-function tickNpc(npc,dt){const asleep=npc.activity==='sleep';let dx=npc.target.x-npc.x,dz=npc.target.z-npc.z,dist=Math.hypot(dx,dz);if(!asleep&&dist<.65)chooseNpcTarget(npc);dx=npc.target.x-npc.x;dz=npc.target.z-npc.z;dist=Math.hypot(dx,dz);const moving=!asleep&&dist>.25;if(moving){const step=Math.min(dist,npc.speed*dt),nx=npc.x+dx/dist*step,nz=npc.z+dz/dist*step;if(!npcCollides(nx,npc.z,.62))npc.x=nx;if(!npcCollides(npc.x,nz,.62))npc.z=nz}let socialFriend=null;if(npc.activity==='social'){for(const other of npcState){if(other!==npc&&other.activity==='social'&&Math.hypot(other.x-npc.x,other.z-npc.z)<7){socialFriend=other;break}}}if(socialFriend)npc.dir=Math.atan2(socialFriend.x-npc.x,socialFriend.z-npc.z);else if(moving)npc.dir=Math.atan2(dz,dx);npc.group.rotation.y=-npc.dir+Math.PI/2;const phase=(npc.phase+=dt*(npc.activity==='eat'?6:2.5));const breathing=Math.sin(phase)*.025;const bob=moving?Math.abs(Math.sin(phase*2))*.07:breathing;if(asleep){npc.group.rotation.z=1.48;npc.group.position.set(npc.x,.3+Math.sin(phase)*.035,npc.z)}else{npc.group.rotation.z=0;npc.group.position.set(npc.x,bob,npc.z)}if(npc.activity==='eat')npc.group.rotation.x=Math.sin(phase)*.045;else npc.group.rotation.x=0}
